import sqlite3
import json
import ast
from typing import Any, Dict, List, Tuple
from collections import defaultdict

# Milvus
from pymilvus import connections, Collection

# Embedding model for query vector
from sentence_transformers import SentenceTransformer


# ----------------------------
# Fixed configuration (as required)
# ----------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ----------------------------
# Helpers
# ----------------------------

def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def safe_parse_attributes(val: Any) -> Dict[str, Any]:
    """Yelp attributes often stored as JSON string or Python dict-like string."""
    if val is None:
        return {}
    if isinstance(val, dict):
        return val
    if isinstance(val, (bytes, bytearray)):
        val = val.decode('utf-8', errors='ignore')
    if not isinstance(val, str):
        return {}

    s = val.strip()
    if not s:
        return {}

    # Try JSON
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        pass

    # Try Python literal
    try:
        obj = ast.literal_eval(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def norm_bool(x: Any) -> Any:
    if isinstance(x, bool):
        return x
    if isinstance(x, str):
        t = x.strip().lower()
        if t in ("true", "1", "yes"):
            return True
        if t in ("false", "0", "no"):
            return False
    return x


def wifi_is_good(attrs: Dict[str, Any]) -> bool:
    wifi = attrs.get('WiFi') or attrs.get('wifi')
    if wifi is None:
        return False
    if isinstance(wifi, str):
        w = wifi.strip().lower().strip("'")
        return w in ("free", "paid")
    return False


def good_for_groups(attrs: Dict[str, Any]) -> bool:
    g = attrs.get('GoodForGroups')
    g = norm_bool(g)
    return g is True


def chunk_list(xs: List[str], size: int) -> List[List[str]]:
    return [xs[i:i+size] for i in range(0, len(xs), size)]


# ----------------------------
# Step 1/2: Candidate selection from SQLite business.db
# ----------------------------

def load_candidate_businesses(city: str = "Tucson", limit: int = 4000) -> List[Dict[str, Any]]:
    conn = connect_sqlite(sqlite_paths["business"])
    try:
        q = """
        SELECT business_id, name, address, city, state, postal_code,
               latitude, longitude, stars, review_count, categories, attributes
        FROM business
        WHERE city = ?
          AND (categories LIKE '%Cafe%' OR categories LIKE '%Coffee%' OR categories LIKE '%Restaurant%')
        LIMIT ?;
        """
        rows = conn.execute(q, (city, limit)).fetchall()
        out = []
        for r in rows:
            d = dict(r)
            attrs = safe_parse_attributes(d.get('attributes'))
            d['_attrs'] = attrs
            out.append(d)
        return out
    finally:
        conn.close()


def filter_businesses(biz: List[Dict[str, Any]], allow_unknown_wifi_with_text_evidence: bool = True) -> List[Dict[str, Any]]:
    """Keep businesses that likely fit based on structured attributes.

    If allow_unknown_wifi_with_text_evidence=True, we keep entries that have GoodForGroups
    even if WiFi attribute is missing; Milvus text evidence can rescue them.
    """
    filtered = []
    for b in biz:
        attrs = b.get('_attrs', {})
        has_groups = good_for_groups(attrs)
        has_wifi = wifi_is_good(attrs)

        if has_wifi and has_groups:
            filtered.append(b)
        else:
            if allow_unknown_wifi_with_text_evidence and has_groups:
                filtered.append(b)

    return filtered


# ----------------------------
# Step 3: Vector search in Milvus (reviews + tips)
# ----------------------------

def milvus_connect():
    connections.connect(
        alias="default",
        host=milvus_config['milvus_host'],
        port=milvus_config['milvus_port']
    )


def milvus_search_evidence(
    business_ids: List[str],
    query_text: str,
    topk_per_collection: int = 200,
    max_ids_per_expr: int = 800,
) -> List[Dict[str, Any]]:
    """Search both reviews and tips collections for evidence.

    Returns list of hits: {collection, business_id, item_id, score}
    score: smaller distance means more similar for L2; for IP/cosine may be larger better.
    We'll keep raw score and later normalize heuristically.
    """
    milvus_connect()

    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    qvec = model.encode([query_text], normalize_embeddings=True).tolist()

    hits = []

    def do_search(collection_name: str, id_field_candidates: List[str]):
        col = Collection(collection_name)
        col.load()

        # Detect an ID field for text item (review_id/tip_id) best-effort
        schema_fields = {f.name for f in col.schema.fields}
        item_id_field = None
        for c in id_field_candidates:
            if c in schema_fields:
                item_id_field = c
                break

        # Detect embedding field best-effort
        emb_field = None
        for candidate in ("embedding", "vector", "emb", "text_vector"):
            if candidate in schema_fields:
                emb_field = candidate
                break
        if emb_field is None:
            # fallback to first FLOAT_VECTOR field
            for f in col.schema.fields:
                if str(f.dtype).endswith("FLOAT_VECTOR"):
                    emb_field = f.name
                    break
        if emb_field is None:
            raise RuntimeError(f"Cannot find vector field in Milvus collection {collection_name}")

        # Ensure business_id exists
        if "business_id" not in schema_fields:
            raise RuntimeError(f"Milvus collection {collection_name} missing required field business_id")

        output_fields = ["business_id"]
        if item_id_field:
            output_fields.append(item_id_field)

        # Milvus expr list can get too long; search in chunks
        for chunk in chunk_list(business_ids, max_ids_per_expr):
            # escape single quotes
            esc = [x.replace("'", "\\'") for x in chunk]
            expr = "business_id in [" + ",".join([f"'{x}'" for x in esc]) + "]"

            res = col.search(
                data=qvec,
                anns_field=emb_field,
                param={"metric_type": "COSINE", "params": {"ef": 64}},
                limit=topk_per_collection,
                expr=expr,
                output_fields=output_fields,
                consistency_level="Bounded"
            )

            for hit in res[0]:
                ent = hit.entity
                bid = ent.get("business_id") if hasattr(ent, 'get') else ent["business_id"]
                item_id = None
                if item_id_field:
                    item_id = ent.get(item_id_field) if hasattr(ent, 'get') else ent[item_id_field]
                hits.append({
                    "collection": collection_name,
                    "business_id": bid,
                    "item_id": item_id,
                    "score": float(hit.score)
                })

    do_search(milvus_config['milvus_collections']['reviews'], ["review_id", "id", "pk"])
    do_search(milvus_config['milvus_collections']['tips'], ["tip_id", "id", "pk", "rowid"])

    return hits


# ----------------------------
# Step 4: Fetch text snippets from SQLite review/tip
# ----------------------------

def fetch_review_texts(review_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    if not review_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["review"])
    try:
        placeholders = ",".join(["?"] * len(review_ids))
        q = f"SELECT review_id, business_id, text, stars, date FROM review WHERE review_id IN ({placeholders});"
        rows = conn.execute(q, review_ids).fetchall()
        return {r["review_id"]: dict(r) for r in rows}
    finally:
        conn.close()


def fetch_tip_texts_by_rowid(rowids: List[int]) -> Dict[int, Dict[str, Any]]:
    """Some datasets don’t have tip_id; Milvus may store SQLite rowid.
    We support rowid lookup if item_id is numeric.
    """
    if not rowids:
        return {}
    conn = connect_sqlite(sqlite_paths["tip"])
    try:
        placeholders = ",".join(["?"] * len(rowids))
        q = f"SELECT rowid as _rowid, user_id, business_id, text, date FROM tip WHERE rowid IN ({placeholders});"
        rows = conn.execute(q, rowids).fetchall()
        return {int(r["_rowid"]): dict(r) for r in rows}
    finally:
        conn.close()


# ----------------------------
# Ranking / scoring
# ----------------------------

def compute_ranked_results(
    businesses: List[Dict[str, Any]],
    hits: List[Dict[str, Any]],
    top_n: int = 10,
) -> List[Dict[str, Any]]:

    biz_by_id = {b["business_id"]: b for b in businesses}

    # Aggregate evidence
    agg = defaultdict(lambda: {
        "review_hits": [],
        "tip_hits": [],
        "best_score": None,
        "hit_count": 0
    })

    for h in hits:
        bid = h["business_id"]
        if bid not in biz_by_id:
            continue
        rec = agg[bid]
        rec["hit_count"] += 1
        rec["best_score"] = h["score"] if rec["best_score"] is None else max(rec["best_score"], h["score"])
        if h["collection"] == milvus_config['milvus_collections']['reviews']:
            rec["review_hits"].append(h)
        else:
            rec["tip_hits"].append(h)

    # Fetch a few texts for evidence
    # Review IDs likely strings; Tip IDs might be rowid integers.
    review_ids = []
    tip_rowids = []

    for bid, rec in agg.items():
        for rh in sorted(rec["review_hits"], key=lambda x: x["score"], reverse=True)[:3]:
            if rh["item_id"]:
                review_ids.append(str(rh["item_id"]))
        for th in sorted(rec["tip_hits"], key=lambda x: x["score"], reverse=True)[:2]:
            if th["item_id"] is not None:
                # try int
                try:
                    tip_rowids.append(int(th["item_id"]))
                except Exception:
                    pass

    review_text_map = fetch_review_texts(list(sorted(set(review_ids))))
    tip_text_map = fetch_tip_texts_by_rowid(list(sorted(set(tip_rowids))))

    def snippet(t: str, n: int = 220) -> str:
        t = (t or "").replace("\n", " ").strip()
        return t if len(t) <= n else t[:n] + "..."

    results = []
    for bid, b in biz_by_id.items():
        attrs = b.get('_attrs', {})
        a = agg.get(bid)
        if not a:
            continue

        # Composite score (heuristic):
        # - milvus best_score (COSINE): higher is better
        # - hit_count: more mentions is better
        # - stars & review_count: quality/popularity priors
        stars = float(b.get("stars") or 0.0)
        rc = int(b.get("review_count") or 0)
        best_sim = float(a.get("best_score") or 0.0)
        hit_count = int(a.get("hit_count") or 0)

        composite = (
            2.5 * best_sim +
            0.15 * min(hit_count, 20) +
            0.35 * stars +
            0.10 * (min(rc, 500) / 100.0)
        )

        evidence = []
        for rh in sorted(a["review_hits"], key=lambda x: x["score"], reverse=True)[:2]:
            rid = rh["item_id"]
            if rid and str(rid) in review_text_map:
                r = review_text_map[str(rid)]
                evidence.append({
                    "type": "review",
                    "similarity": rh["score"],
                    "text": snippet(r.get("text", ""))
                })
        for th in sorted(a["tip_hits"], key=lambda x: x["score"], reverse=True)[:2]:
            try:
                rowid = int(th["item_id"]) if th["item_id"] is not None else None
            except Exception:
                rowid = None
            if rowid is not None and rowid in tip_text_map:
                t = tip_text_map[rowid]
                evidence.append({
                    "type": "tip",
                    "similarity": th["score"],
                    "text": snippet(t.get("text", ""))
                })

        results.append({
            "business_id": bid,
            "name": b.get("name"),
            "address": b.get("address"),
            "city": b.get("city"),
            "state": b.get("state"),
            "postal_code": b.get("postal_code"),
            "stars": stars,
            "review_count": rc,
            "categories": b.get("categories"),
            "attributes": {
                "WiFi": attrs.get("WiFi"),
                "GoodForGroups": attrs.get("GoodForGroups"),
                "NoiseLevel": attrs.get("NoiseLevel"),
                "OutdoorSeating": attrs.get("OutdoorSeating"),
                "RestaurantsTableService": attrs.get("RestaurantsTableService"),
            },
            "milvus": {
                "best_similarity": best_sim,
                "hit_count": hit_count
            },
            "score": composite,
            "evidence": evidence
        })

    results.sort(key=lambda x: x["score"], reverse=True)
    return results[:top_n]


def main():
    query_text = (
        "tech-friendly cafe or restaurant with good wifi, power outlets, plenty of space, "
        "quiet enough for work, and suitable for group discussions or meetings"
    )

    # 1) SQL candidates
    candidates = load_candidate_businesses(city="Tucson", limit=4000)

    # 2) Attribute filter (soft)
    filtered = filter_businesses(candidates, allow_unknown_wifi_with_text_evidence=True)

    if not filtered:
        print("No candidates found after filtering.")
        return

    business_ids = [b["business_id"] for b in filtered]

    # 3) Vector search evidence in Milvus
    try:
        hits = milvus_search_evidence(
            business_ids=business_ids,
            query_text=query_text,
            topk_per_collection=200,
            max_ids_per_expr=800
        )
    except Exception as e:
        print("Milvus search failed:", e)
        print("Tip: check Milvus is running, collections exist, and schema has business_id + vector field.")
        return

    # 4) Rank and print
    results = compute_ranked_results(filtered, hits, top_n=10)

    print("\nTop tech-friendly cafes/restaurants in Tucson (heuristic ranking):\n")
    for i, r in enumerate(results, 1):
        print(f"#{i} {r['name']} | {r['stars']}⭐ ({r['review_count']} reviews) | score={r['score']:.3f}")
        print(f"   {r['address']}, {r['city']}, {r['state']} {r['postal_code']}")
        print(f"   WiFi={r['attributes'].get('WiFi')} | GoodForGroups={r['attributes'].get('GoodForGroups')} | NoiseLevel={r['attributes'].get('NoiseLevel')}")
        if r["evidence"]:
            for ev in r["evidence"][:3]:
                print(f"   - ({ev['type']}, sim={ev['similarity']:.3f}) {ev['text']}")
        print("")


if __name__ == "__main__":
    main()
